save(906,{3:'名称：伊格纳图斯枢机（原稿另译伊格纳修斯枢机）。',7:'类别：红衣主教世界。',9:'伊格纳图斯枢机，也简称伊格纳图斯，是帝国的一颗世界。',12:'星球上设有伊格纳图斯第一忠嗣学院。从学院可以望见首都伊格纳图斯，以及行星上最重要的国教会圣殿；圣殿塔楼高逾两公里。这颗世界以寒冷、潮湿、昏暗著称。',14:'著名校友包括上校政委伊布拉姆·冈特，以及政委维诺姆·布伦纳。',17:'伊格纳图斯——首都城市。'},title='伊格纳图斯枢机 Ignatius Cardinal',notes={3:'行星专名沿866篇既有全名伊格纳图斯枢机；Cardinal World类别译红衣主教世界，不把地名里的Cardinal一并改成职衔。人物Ignatius另按具体身份，不与本地名合并。',14:'Colonel-Commissar 是上校兼政委的双重职衔，不能仅译兵团政委。冈特姓氏可参考已核官方Gaunt’s Ghosts＝冈特的幽灵，人物全名仍待核。'},terms=[('Ignatius (city)','伊格纳图斯（城市）'),('Schola Progenium Prime of Ignatius','伊格纳图斯第一忠嗣学院'),('Ibram Gaunt','伊布拉姆·冈特'),('Colonel-Commissar','上校政委'),('Vaynom Blenner','维诺姆·布伦纳')])
save(907,{10:'356—372.M31年，极限战士军团为在罗瑟恩一号斯塔伦伯格曲折的街巷中使用重型攻城武器，研制了维护者战车。科技战士改装宏炮的炮尾与炮管组件，将其装入结构加固的犀牛装甲运兵车。这些早期维护者在拥挤的城市战场上表现出色：异端军队在有限街区内所能部署的火力，远远不及它们。维护者战车为夺回斯塔伦伯格立下重要功劳，也帮助帝国最终平定整颗罗瑟恩一号。'},notes={10:'Vindicator依官方维护者战车；Techmarine依官方科技战士，不译技术军士。macro-cannon为宏炮，未泛化成任意大口径火炮。'},terms=[('Rothern I','罗瑟恩一号'),('Stahlenberg','斯塔伦伯格')])
save(908,{2:'庄严星曾是黑色圣堂的母星与征募据点。',11:'类别：封建世界、原星际战士母星、禁忌世界。',13:'什一税等级：Aptus Non（现稿暂译特级免税）。',16:'据认为，人类最早于遥远的黑暗科技时代在庄严星定居。按底稿所述，约一千年前，埃姆里克元帅率黑色圣堂来到这里，镇压一个隐秘的基因窃取者教派；彼时，该教派几乎已控制整颗星球。清除污染后，黑色圣堂将庄严星纳入掌控，作为征募世界，并在当地维持一座修道院要塞，供远征间隙补给及挑选新兵。要塞常驻一百名战斗兄弟，另有新进者、仆役、文吏及其他人员，照料战团与要塞的需要。',18:'庄严星常受风暴侵袭，居民依靠养羊、林业、其他畜牧业及基础采矿、采石维生。当地仍保留由小王国和附庸领主构成的统治制度，但真正的最高统治者是修道院要塞的堡主。他实际承担行星总督之责，代表庄严星与更广阔的帝国打交道。',20:'布兰特元帅的黑色圣堂舰队在阿波罗次星区参加卢格纳萨德解放战后，正准备返回庄严星。就在此时，战争头目莫尔克鲁尔·格里姆斯卡率血疤部落舰队来袭。欧克首先对修道院要塞展开轨道轰炸，但攻击被护盾发生器挡住。它们随后让一座巨石战堡撞落在要塞附近。坠地冲击加上巨石战堡的近距离炮击，使要塞护盾过载崩溃，部分城墙也遭摧毁。大批欧克涌入，将里面的人屠戮殆尽。',22:'布兰特舰队抵达时，发现庄严星正遭攻击。黑色圣堂先迎击欧克舰队，迫使敌舰在炮火中后退，再向行星投放空降舱。战斗兄弟在要塞废墟中与欧克激战，最终杀光了庄严星上的欧克。他们搜寻废墟，只有贾罗德兄弟尚存一息，倒在一堆欧克尸体上。伤势太重，唯有将他安置进无畏机甲，才能延续他的生命。',24:'战斗结束后不久，黑色圣堂摧毁要塞残迹，撤离庄严星。这颗世界从此不再为黑色圣堂征募新兵；离去的战士在轨道留下警告信标，也阻止其他战团在此征募。整个世界成为纪念地，悼念血疤部落袭击中阵亡的兄弟，成为黑色圣堂珍藏的又一件圣遗物。',26:'布兰特率残部继续追击欧克，并将行动改名为庄严远征。他们发誓，要向莫尔克鲁尔·格里姆斯卡麾下的兽潮复仇，为阵亡兄弟讨还血债。'},notes={16:'millennia-distant 不等于仅距今一千年；另一句“A thousand years before”未明示参照事件，保留约千年前而不补绝对纪年。',20:'Rok 是欧克改造的巨石战堡，由欧克主动送向地面，原译被击落错误。',22:'原英文首句缺谓语，依舰队返抵语境补足；投放空降舱者是黑色圣堂，不是正在撤退的欧克舰队。',24:'警告信标使其他战团也不再在此征募，原句残缺，已恢复完整意思。'},terms=[('Solemnus','庄严星'),('Emrik','埃姆里克'),('Brant','布兰特'),('Blood Scar','血疤部落'),('Morkrull Grimskar','莫尔克鲁尔·格里姆斯卡'),('Jarold','贾罗德'),('Solemnus Crusade','庄严远征'),('Apollo Subsector','阿波罗次星区')])
save(909,{11:'皮希纳四号是帝国的一颗矿业行星，曾设有暗黑天使的据点。',14:'皮希纳四号虽在帝国控制下，却始终与欧克交战。每当欧克似乎被击败，驻防的帝国卫队各团又会在别处遭到袭击。欧克常藏身废弃矿井口，构筑巢穴与阵地，直到聚集足够数量，便冲垮前来清剿的卫队。近些年，天使之塔造访暗黑天使据点的次数越来越少，大约每隔一代人才来一次，接走从原始的皮希纳五号选拔来的候选者，让他们接受进一步考验与改造。',19:'驻守行星的暗黑天使小队包括：',21:'审讯教士波瑞亚斯——当地暗黑天使部队的负责人。',23:'科技战士赫菲斯托斯——负责装备维修，以及要塞地下的湮灭病毒武器。',25:'药剂师内斯特——照料小队成员健康，守护保存在行星上的基因种子。',29:'老兵军士达马斯——训练从星外征集的候选者，直到他们乘天使之塔离开。',31:'塞弗率领的堕天使为盗取医疗部秘库中的基因种子，策划了一场错综复杂的阴谋。小队全员最终因此死在自己的要塞之内。',33:'要塞的病毒武器应急装置被触发，足以消灭星球上的全部生命。波瑞亚斯意识到，保护居民的唯一办法，就是保持要塞大门气密封闭，将病毒困在里面，直至它失活。内斯特肩负保全基因种子的职责，试图离开，却被波瑞亚斯用赫菲斯托斯的等离子手枪射杀。其余星际战士不愿等到饥渴动摇意志、迫使自己开门求生，于是将热熔炸弹紧贴胸口，一边向原体莱昂·艾尔’庄森祈祷，一边引爆炸弹，结束了生命。',35:'事后，萨麦尔大导师率鸦翼抵达要塞，调查驻军失踪一事。',37:'第四十二千年，皮希纳四号再次遭欧克大军入侵，暗黑天使又一次前来保卫它。'},notes={14:'dig themselves in 指挖掘工事并据守，不是“自掘”；aspirants 为新兵候选者。',21:'此处 Boreas 是暗黑天使审讯教士，与660篇同名帝国之拳副官不是同一人物；采用相同音译但分列身份。',23:'under the keep 指武器位于要塞地下，原译遗漏位置。',29:'off-world 为星外，不是本星球各地。',33:'failsafe 为触发病毒武器的应急装置，避免将其误解为设备偶然故障；Lion姓名依已核核心统一。'},terms=[('Piscina System','皮希纳星系'),('Boreas (Dark Angels)','波瑞亚斯（暗黑天使）'),('Hephaestus','赫菲斯托斯'),('Nestor','内斯特'),('Thumiel','图米尔'),('Zaul','扎乌尔'),('Damas','达马斯'),('Annihilus Virus','湮灭病毒'),('Tower of Angels','天使之塔')])
save(910,{9:'艾米琳之希望是国教会的一颗圣地世界，以供奉圣艾米琳的遗骨闻名。',11:'452.M41年，卡尔韦拉的“大狂人”率领欧克大蛮干！袭击该世界，最终被负责守护星球的战斗修女流血之心修会击败。'},notes={11:'被击败的是欧克攻势，并非世界本身；拆开原句，明确保卫者与入侵者。'},terms=[('Saint Emiline','圣艾米琳'),('Order of the Bleeding Heart','流血之心修会'),('Arch Maniac of Calvera','卡尔韦拉的大狂人'),('Caprium','卡普里姆')])
